public class GrayPaintScale_getPaint_TriageGen0Test {

    @Test
    public void testGetPaint_WithinBounds() {
        // Test a value exactly in the middle
        GrayPaintScale scale = new GrayPaintScale(0.0, 100.0);
        Paint paint = scale.getPaint(50.0);

        // Calculation: (50 - 0) / (100 - 0) * 255 = 0.5 * 255 = 127.5 -> (int) 127
        Color color = (Color) paint;
        assertEquals(127, color.getRed());
        assertEquals(127, color.getGreen());
        assertEquals(127, color.getBlue());
    }

    @Test
    public void testGetPaint_AtLowerBound() {
        GrayPaintScale scale = new GrayPaintScale(10.0, 20.0);
        Paint paint = scale.getPaint(10.0);

        // Calculation: (10 - 10) / (20 - 10) * 255 = 0
        Color color = (Color) paint;
        assertEquals(0, color.getRed());
    }

    @Test
    public void testGetPaint_AtUpperBound() {
        GrayPaintScale scale = new GrayPaintScale(0.0, 10.0);
        Paint paint = scale.getPaint(10.0);

        // Calculation: (10 - 0) / (10 - 0) * 255 = 255
        Color color = (Color) paint;
        assertEquals(255, color.getRed());
    }

