    @Test
    public void testGetPaint_AboveUpperBound() {
        // This tests the Math.min(v, this.upperBound) branch
        GrayPaintScale scale = new GrayPaintScale(0.0, 100.0);
        Paint paint = scale.getPaint(150.0);

        // Calculation: (150 - 0) / (100 - 0) * 255 = 1.5 * 255 = 382.5 -> (int) 382
        // java.awt.Color will throw IllegalArgumentException if components > 255.
        try {
            Color color = (Color) paint;
            assertEquals(382, color.getRed());
