    @Test
    public void testGetPaint_ExtremeBounds() {
        // Test with very small range
        GrayPaintScale scale = new GrayPaintScale(0.0, 1.0);
        Paint paint = scale.getPaint(0.5);
        Color color = (Color) paint;
        assertEquals(127, color.getRed());
